input.content:
"""Deterministic crop suitability scoring.

The score is intentionally explainable: every crop gets a 0-100 score plus a
component breakdown. The rule engine is the "anchor" of the product; the LLM
can re-rank and explain, but it cannot silently replace the agronomic maths.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Iterable

from app.domain.crops import CROPS, CropProfile, TEXTURE_GROUP, resolve_crops
from app.schemas import (
    AnalyzeRequest,
    EnvironmentSnapshot,
    Goal,
    Irrigation,
    SoilTexture,
    WaterAvailability,
)
from app.services.agronomy import (
    SeasonMetrics,
    band_score,
    irrigation_supply_mm,
    season_metrics,
)

COMPONENT_WEIGHTS: dict[str, float] = {
    "temperature": 0.20,
    "water": 0.24,
    "ph": 0.10,
    "texture": 0.10,
    "salinity": 0.04,
    "climate_risk": 0.10,
    "goal_fit": 0.14,
    "market": 0.05,
    "calendar": 0.03,
}

COMPONENT_LABELS_TR = {
    "temperature": "Sıcaklık",
    "water": "Su dengesi",
    "ph": "Toprak pH'ı",
    "texture": "Toprak dokusu",
    "salinity": "Tuzluluk",
    "climate_risk": "İklim riski",
    "goal_fit": "Hedefe uygunluk",
    "market": "Pazar",
    "calendar": "Ekim takvimi",
}

TEXTURE_ORDER = ["light", "light_medium", "medium", "medium_heavy", "heavy"]

NITROGEN_FACTOR = {"low": 1.0, "medium": 0.6, "high": 0.25}


@dataclass
class CropEvaluation:
    crop: CropProfile
    rule_score: float
    components: dict[str, float | None]
    strengths: list[str] = field(default_factory=list)
    limiting_factors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)
    season: SeasonMetrics | None = None
    water_ratio: float | None = None
    irrigation_supply_mm: float = 0.0
    confidence: str = "medium"
    interest_boost: float = 0.0

    @property
    def data_completeness(self) -> float:
        present = sum(1 for value in self.components.values() if value is not None)
        return present / len(COMPONENT_WEIGHTS)


def _circular_distance(month: int, target: int) -> int:
    raw = abs(month - target)
    return min(raw, 12 - raw)


def _texture_score(field_texture: SoilTexture, crop: CropProfile) -> float | None:
    if field_texture == SoilTexture.UNKNOWN:
        return None
    actual_group = TEXTURE_GROUP.get(field_texture.value)
    if actual_group is None:
        return None
    preferred_groups = {
        TEXTURE_GROUP[texture]
        for texture in crop.textures
        if texture in TEXTURE_GROUP
    }
    if not preferred_groups:
        return None
    if actual_group in preferred_groups:
        return 100.0
    distance = min(abs(TEXTURE_ORDER.index(actual_group) - TEXTURE_ORDER.index(group)) for group in preferred_groups)
    return max(0.0, 100.0 - 22.0 * distance)


def _salinity_score(field_salinity: float | None, crop: CropProfile) -> float | None:
    if field_salinity is None:
        return None
    threshold = 1.2 + 5.5 * crop.salinity_tolerance
    if field_salinity <= threshold:
        return 100.0
    return max(0.0, 100.0 - (field_salinity - threshold) * 20.0)


def _goal_fit_score(crop: CropProfile, goal: Goal) -> float:
    low_nitrogen = NITROGEN_FACTOR.get(crop.nitrogen_need, 0.5)
    if goal == Goal.MAX_YIELD:
        value = crop.yield_potential
    elif goal == Goal.MAX_PROFIT:
        value = 0.55 * crop.gross_margin + 0.45 * crop.market_demand
    elif goal == Goal.LOW_WATER:
        value = 0.6 * crop.drought_tolerance + 0.4 * (1 - min(crop.water_need_mm, 900) / 900)
    elif goal == Goal.LOW_INPUT:
        value = 0.5 * low_nitrogen + 0.3 * crop.organic_suitability + 0.2 * crop.drought_tolerance
    elif goal == Goal.ORGANIC:
        value = crop.organic_suitability
    elif goal == Goal.SOIL_HEALTH:
        value = 0.55 * crop.organic_suitability + 0.45 * (1.0 if crop.is_legume else 0.4)
    elif goal == Goal.RISK_AVERSE:
        value = (
            0.4 * crop.frost_tolerance
            + 0.3 * crop.drought_tolerance
            + 0.3 * crop.market_demand
        )
    else:  # pragma: no cover - enum is exhaustive
        value = 0.5
    return round(100.0 * value, 1)


def _market_score(crop: CropProfile, market_access: str) -> float:
    value = 100.0 * crop.market_demand
    if market_access == "low":
        value = min(value, 70.0)
    elif market_access == "high":
        value = min(100.0, value + 5.0)
    return round(value, 1)


def _calendar_score(crop: CropProfile, preferred_month: int | None) -> float:
    if preferred_month is None:
        return 100.0
    distance = min(_circular_distance(preferred_month, month) for month in crop.planting_months)
    if distance == 0:
        return 100.0
    if distance == 1:
        return 85.0
    if distance == 2:
        return 50.0
    return 25.0


def _climate_risk_score(
    crop: CropProfile,
    season: SeasonMetrics,
    environment: EnvironmentSnapshot,
    irrigation: Irrigation,
) -> float:
    frost_penalty = len(season.frost_months) * (1.0 - crop.frost_tolerance) * 14.0
    heat_penalty = len(season.heat_months) * (1.0 - crop.heat_tolerance) * 12.0
    score = 100.0 - frost_penalty - heat_penalty

    climate_class = environment.climate.climate_class or "unknown"
    aridity_penalty = {
        "hyper_arid": 22.0,
        "arid": 18.0,
        "semi_arid": 10.0,
        "dry_sub_humid": 4.0,
    }.get(climate_class, 0.0)
    if irrigation == Irrigation.LIMITED:
        aridity_penalty *= 0.5
    elif irrigation == Irrigation.FULL:
        aridity_penalty = 0.0
    return max(0.0, min(100.0, score - aridity_penalty))


def _water_score(
    crop: CropProfile,
    season: SeasonMetrics,
    irrigation_supply: float,
    irrigation: Irrigation,
) -> tuple[float | None, float | None]:
    if season.total_precip_mm is None:
        return None, None
    supply = season.total_precip_mm + irrigation_supply
    ratio = supply / crop.water_need_mm
    if ratio < 0.95:
        deficit = 1.0 - ratio
        score = 100.0 - deficit * 140.0 * (1.0 - 0.6 * crop.drought_tolerance)
    elif ratio > 1.7:
        score = max(50.0, 100.0 - (ratio - 1.7) * 30.0)
    else:
        score = 100.0
    return round(max(0.0, min(100.0, score)), 1), round(ratio, 3)


def _build_messages(
    crop: CropProfile,
    components: dict[str, float | None],
    season: SeasonMetrics,
    water_ratio: float | None,
) -> tuple[list[str], list[str]]:
    strengths: list[str] = []
    limits: list[str] = []

    for key, score in components.items():
        if score is None:
            continue
        label = COMPONENT_LABELS_TR[key]
        if key == "temperature" and score >= 80:
            strengths.append(f"Sıcaklık uygun ({season.mean_temp_c}°C)")
        elif key == "water" and score >= 80:
            strengths.append(
                f"Su dengesi uygun (sezon yağışı {season.total_precip_mm} mm, oran {water_ratio})"
            )
        elif key == "ph" and score >= 80:
            strengths.append("Toprak pH'ı uygun")
        elif key == "texture" and score >= 80:
            strengths.append("Toprak dokusu uygun")
        elif key == "salinity" and score >= 80:
            strengths.append("Tuzluluk riski düşük")
        elif key == "market" and score >= 80:
            strengths.append("Pazar talebi güçlü")
        elif key == "goal_fit" and score >= 80:
            strengths.append("Çiftçinin hedefiyle güçlü uyum")
        elif score <= 50 and key == "temperature":
            limits.append(
                f"Sıcaklık sınırda (sezon ort. {season.mean_temp_c}°C; optimum "
                f"{crop.temp_opt[0]}-{crop.temp_opt[1]}°C)"
            )
        elif score <= 50 and key == "water":
            limits.append(
                f"Su açığı var (sezon yağışı {season.total_precip_mm} mm, "
                f"ihtiyaç {crop.water_need_mm} mm, oran {water_ratio})"
            )
        elif score <= 50 and key == "ph":
            limits.append(f"Toprak pH'ı sınırda (optimum {crop.ph_opt[0]}-{crop.ph_opt[1]})")
        elif score <= 50 and key == "texture":
            limits.append("Toprak dokusu bu ekin için ideal değil")
        elif score <= 50 and key == "salinity":
            limits.append("Tuzluluk bu ekin için risk oluşturabilir")
        elif score <= 50 and key == "climate_risk":
            limits.append(
                f"İklim riski yüksek (don ayları: {len(season.frost_months)}, "
                f"sıcak stresi ayları: {len(season.heat_months)})"
            )
        elif score <= 50 and key == "calendar":
            limits.append("Ekim takvimi çiftçinin planladığı aydan uzak")
        elif score <= 50 and key == "market":
            limits.append("Pazar erişimi bu ürün için sınırlı olabilir")
        elif score <= 50 and key == "goal_fit":
            limits.append(f"{label} seçilen hedefe göre düşük")

    return strengths, limits


def evaluate_crop(
    crop: CropProfile,
    request: AnalyzeRequest,
    environment: EnvironmentSnapshot,
) -> CropEvaluation:
    field = request.field
    resources = request.resources
    season = season_metrics(environment, crop, request.preferences.planting_month)
    irrigation_supply = irrigation_supply_mm(resources)

    components: dict[str, float | None] = {}
    components["temperature"] = (
        None
        if season.mean_temp_c is None
        else round(
            band_score(season.mean_temp_c, crop.temp_opt, crop.temp_abs) or 0.0,
            1,
        )
    )
    water_score, water_ratio = _water_score(crop, season, irrigation_supply, resources.irrigation)
    components["water"] = water_score
    components["ph"] = (
        None if field.soil_ph is None else band_score(field.soil_ph, crop.ph_opt, crop.ph_abs)
    )
    components["texture"] = _texture_score(field.soil_texture, crop)
    components["salinity"] = _salinity_score(field.salinity_ds_m, crop)
    components["climate_risk"] = _climate_risk_score(crop, season, environment, resources.irrigation)
    components["goal_fit"] = _goal_fit_score(crop, request.preferences.goal)
    components["market"] = _market_score(crop, request.preferences.market_access.value)
    components["calendar"] = _calendar_score(crop, request.preferences.planting_month)

    present = {key: value for key, value in components.items() if value is not None}
    total_weight = sum(COMPONENT_WEIGHTS[key] for key in present)
    score = (
        sum(value * COMPONENT_WEIGHTS[key] for key, value in present.items()) / total_weight
        if total_weight
        else 0.0
    )

    # Hard agronomic limits: an unsuitable crop must not look good because of
    # strong market or goal-fit components.
    if components["temperature"] == 0:
        score *= 0.35
    if components["water"] == 0 and resources.irrigation == Irrigation.RAINFED:
        score *= 0.5
    if components["ph"] == 0:
        score *= 0.65

    strengths, limits = _build_messages(crop, components, season, water_ratio)

    warnings: list[str] = []
    if water_ratio is not None and water_ratio < 0.7:
        warnings.append(
            f"{crop.local_name}: sezonluk su açığı ({(water_ratio * 100):.0f}% karşılama). "
            "Sulama imkânı yoksa verim düşer."
        )
    if season.frost_months and crop.frost_tolerance < 0.4:
        warnings.append(
            f"{crop.local_name}: sezon içinde don riski olan aylar var "
            f"({', '.join(season.frost_months)})."
        )

    completeness = len(present) / len(COMPONENT_WEIGHTS)
    confidence = "high" if completeness >= 0.85 else "medium" if completeness >= 0.6 else "low"

    return CropEvaluation(
        crop=crop,
        rule_score=round(max(0.0, min(100.0, score)), 1),
        components={key: (None if value is None else round(value, 1)) for key, value in components.items()},
        strengths=strengths,
        limiting_factors=limits,
        warnings=warnings,
        season=season,
        water_ratio=water_ratio,
        irrigation_supply_mm=irrigation_supply,
        confidence=confidence,
    )


def evaluate_candidates(
    request: AnalyzeRequest,
    environment: EnvironmentSnapshot,
) -> tuple[list[CropEvaluation], list[str]]:
    warnings: list[str] = []
    candidates: list[CropProfile] = list(CROPS)

    if request.preferences.max_growing_days is not None:
        filtered: list[CropProfile] = []
        for crop in candidates:
            if crop.growing_days <= request.preferences.max_growing_days:
                filtered.append(crop)
            else:
                warnings.append(
                    f"{crop.local_name}, {request.preferences.max_growing_days} günlük sezon sınırını "
                    f"aştığı için elendi ({crop.growing_days} gün)."
                )
        candidates = filtered

    excluded, unknown_excluded = resolve_crops(request.preferences.excluded_crops)
    excluded_keys = {crop.key for crop in excluded}
    if excluded_keys:
        before = len(candidates)
        candidates = [crop for crop in candidates if crop.key not in excluded_keys]
        if len(candidates) < before:
            warnings.append(
                "Çiftçinin hariç tuttuğu ekinler değerlendirmeden çıkarıldı: "
                + ", ".join(sorted(crop.local_name for crop in excluded))
            )
    for name in unknown_excluded:
        warnings.append(f"Hariç tutulan ekin adı tanınmadı: '{name}'.")

    interested, unknown_interested = resolve_crops(request.preferences.crops_of_interest)
    interest_keys = {crop.key for crop in interested}
    for name in unknown_interested:
        warnings.append(f"İlgi listesindeki ekin adı tanınmadı: '{name}'.")
    if interest_keys & excluded_keys:
        warnings.append("Aynı ekin hem ilgi listesinde hem hariç listesinde; hariç listesi önceliklidir.")

    evaluations = [evaluate_crop(crop, request, environment) for crop in candidates]

    for evaluation in evaluations:
        if evaluation.crop.key in interest_keys:
            evaluation.interest_boost = 4.0
            evaluation.rule_score = round(min(100.0, evaluation.rule_score + 4.0), 1)
            evaluation.strengths.append("Çiftçinin ilgi gösterdiği ürünlerden biri")

    evaluations.sort(key=lambda item: (item.rule_score, item.crop.market_demand), reverse=True)
    return evaluations, warnings


def component_summary(evaluations: Iterable[CropEvaluation]) -> dict[str, float]:
    """Average component values across evaluations (useful for diagnostics)."""

    totals: dict[str, list[float]] = {}
    for evaluation in evaluations:
        for key, value in evaluation.components.items():
            if value is not None:
                totals.setdefault(key, []).append(value)
    return {key: round(sum(values) / len(values), 2) for key, values in totals.items()}

"""Deterministic, offline "AI fallback" advisor.

This is not a language model. It turns the rule engine's component scores into
a readable recommendation. It guarantees that the API remains useful and
testable without any API key or internet access to an LLM.
"""

from __future__ import annotations

from typing import Any

from app.ai.base import AIAnalysis, AIContext, AICropAssessment, AIProvider
from app.services.agronomy import CLIMATE_CLASS_LABELS_TR


def _tr_list(items: list[str], limit: int = 3) -> str:
    return "; ".join(items[:limit])


def _actions_tr(components: dict[str, float | None], irrigation: str) -> list[str]:
    actions: list[str] = []
    water = components.get("water")
    if water is not None and water < 70:
        if irrigation == "rainfed":
            actions.append(
                "Sulama imkânı yoksa kuraklığa dayanıklı çeşit seçin ve ekim tarihini toprak nemine göre ayarlayın."
            )
        else:
            actions.append("Sezon başı su bütçesini ve sulama programını netleştirin; kritik dönemlerde suyu ayırın.")
    temperature = components.get("temperature")
    if temperature is not None and temperature < 70:
        actions.append("Ekim tarihini yerel don takvimine göre ayarlayın; genç bitkiyi don ve sıcak dalgasından koruyun.")
    ph = components.get("ph")
    if ph is not None and ph < 70:
        actions.append("Toprak analizine göre kireç veya jips uygulamasını yerel uzmanla planlayın.")
    texture = components.get("texture")
    if texture is not None and texture < 70:
        actions.append("Toprak işlemeyi azaltın; organik madde ve malç ile bünyeyi iyileştirin.")
    salinity = components.get("salinity")
    if salinity is not None and salinity < 70:
        actions.append("Drenajı kontrol edin, tuz birikimini izleyin ve gerekiyorsa yıkama sulaması yapın.")
    climate = components.get("climate_risk")
    if climate is not None and climate < 70:
        actions.append("Don/sıcak dalgası sigortası ve risk dağıtımı (farklı tarla/çeşit) değerlendirin.")
    market = components.get("market")
    if market is not None and market < 70:
        actions.append("Ekim öncesi alıcı sözleşmesi, depolama veya kooperatif satış seçeneklerini araştırın.")
    if not actions:
        actions.append("Ekim öncesi sertifikalı tohum, toprak hazırlığı ve gübre planını yerel uzmanla doğrulayın.")
    actions.append("Sezon boyunca yağış, toprak nemi ve hastalık kayıtlarını düzenli tutun.")
    return actions[:5]


def _actions_en(components: dict[str, float | None], irrigation: str) -> list[str]:
    actions: list[str] = []
    water = components.get("water")
    if water is not None and water < 70:
        if irrigation == "rainfed":
            actions.append("If irrigation is unavailable, choose a drought-tolerant variety and align planting with soil moisture.")
        else:
            actions.append("Define the seasonal water budget and protect critical growth stages.")
    temperature = components.get("temperature")
    if temperature is not None and temperature < 70:
        actions.append("Adjust the planting date to the local frost calendar and protect young plants.")
    ph = components.get("ph")
    if ph is not None and ph < 70:
        actions.append("Plan lime or gypsum applications with a local agronomist based on a soil test.")
    texture = components.get("texture")
    if texture is not None and texture < 70:
        actions.append("Reduce tillage and build organic matter / mulch to improve soil structure.")
    salinity = components.get("salinity")
    if salinity is not None and salinity < 70:
        actions.append("Check drainage, monitor salt accumulation and leach if necessary.")
    climate = components.get("climate_risk")
    if climate is not None and climate < 70:
        actions.append("Evaluate frost/heat insurance and risk diversification across fields or varieties.")
    market = components.get("market")
    if market is not None and market < 70:
        actions.append("Explore forward contracts, storage or cooperative sales before planting.")
    if not actions:
        actions.append("Confirm certified seed, soil preparation and fertilisation with a local expert.")
    actions.append("Keep records of rainfall, soil moisture and crop health during the season.")
    return actions[:5]


def _risks_tr(candidate: dict[str, Any]) -> list[str]:
    limits = candidate.get("limiting_factors") or []
    risks = list(limits[:4])
    if not risks:
        risks.append("Belirgin agronomik kısıt yok; yine de fiyat ve hava koşulları belirsizdir.")
    risks.append("NASA POWER grid verisi tarla ölçeğindeki farklılıkları göstermeyebilir.")
    return risks[:4]


def _risks_en(candidate: dict[str, Any]) -> list[str]:
    limits = candidate.get("limiting_factors") or []
    risks = list(limits[:4])
    if not risks:
        risks.append("No major agronomic constraint, but price and weather remain uncertain.")
    risks.append("NASA POWER gridded data may not capture field-scale variability.")
    return risks[:4]


class HeuristicProvider(AIProvider):
    name = "heuristic"
    model = None
    kind = "deterministic"

    def __init__(self, reason: str | None = None) -> None:
        self.reason = reason

    async def analyze(self, context: AIContext) -> AIAnalysis:
        tr = context.language == "tr"
        candidates = context.candidates
        if not candidates:
            return AIAnalysis(
                summary="Değerlendirilecek aday ekin bulunamadı." if tr else "No candidate crops were available.",
                confidence="low",
            )

        top = candidates[0]
        second = candidates[1] if len(candidates) > 1 else None
        region = context.location.get("region_name") or (
            f"{context.location.get('latitude')}, {context.location.get('longitude')}"
        )
        climate = context.environment.get("climate", {})
        climate_class = climate.get("climate_class") or "unknown"
        rainfall = climate.get("annual_precip_mm")
        mean_temp = climate.get("annual_mean_temp_c")

        assessments: list[AICropAssessment] = []
        for candidate in candidates:
            components = candidate.get("component_scores", {}) or {}
            strengths = candidate.get("strengths") or []
            limits = candidate.get("limiting_factors") or []
            irrigation = (context.farmer.get("resources") or {}).get("irrigation", "rainfed")

            if tr:
                rationale_parts = [
                    f"{candidate['crop_name_local']}, bölge koşullarında {candidate['rule_score']}/100 uygunluk aldı."
                ]
                if strengths:
                    rationale_parts.append("Güçlü yönler: " + _tr_list(strengths) + ".")
                if limits:
                    rationale_parts.append("Sınırlar: " + _tr_list(limits) + ".")
                rationale = " ".join(rationale_parts)
                actions = _actions_tr(components, irrigation)
                risks = _risks_tr(candidate)
            else:
                rationale_parts = [
                    f"{candidate['crop_name']} scored {candidate['rule_score']}/100 under the local conditions."
                ]
                if strengths:
                    rationale_parts.append("Strengths: " + "; ".join(strengths[:3]) + ".")
                if limits:
                    rationale_parts.append("Constraints: " + "; ".join(limits[:3]) + ".")
                rationale = " ".join(rationale_parts)
                actions = _actions_en(components, irrigation)
                risks = _risks_en(candidate)

            assessments.append(
                AICropAssessment(
                    crop_key=candidate["crop_key"],
                    ai_score=float(candidate["rule_score"]),
                    rationale=rationale,
                    risks=risks,
                    actions=actions,
                    planting_window=candidate.get("planting_window"),
                )
            )

        gap = top["rule_score"] - (second["rule_score"] if second else 0)
        present_components = sum(
            1 for value in (top.get("component_scores") or {}).values() if value is not None
        )
        if gap < 5 or present_components <= 5:
            confidence = "low"
        elif gap >= 10 and present_components >= 8:
            confidence = "high"
        else:
            confidence = "medium"

        if tr:
            summary = (
                f"{region} için mevcut verilerle en güçlü seçenek {top['crop_name_local']} "
                f"({top['rule_score']}/100)."
            )
            if second:
                summary += f" Ardından {second['crop_name_local']} ({second['rule_score']}/100) geliyor."
            if rainfall is not None and mean_temp is not None:
                summary += (
                    f" Bölge iklimi {CLIMATE_CLASS_LABELS_TR.get(climate_class, climate_class)} "
                    f"sınıfında; yıllık ortalama sıcaklık {mean_temp}°C, yıllık yağış {rainfall} mm."
                )
            summary += (
                " Bu bir ön karar destek çıktısıdır; ekim öncesi yerel tarım uzmanı ve toprak analizi ile doğrulanmalıdır."
            )
            general_risks = [
                "Kuraklık, don ve sıcak dalgası gibi hava olayları verimi düşürebilir.",
                "Girdi fiyatları ve satış fiyatı dalgalanması kârlılığı belirsizleştirir.",
                "NASA POWER verisi tarla ölçeğinde değildir; toprak analizi ve yerel gözlem şarttır.",
            ]
            general_actions = [
                "Ekim öncesi pH, organik madde ve besin elementleri için toprak analizi yaptırın.",
                "İl/ilçe tarım müdürlüğü veya agronomist ile çeşit ve ekim takvimini doğrulayın.",
                "Suyun debisi ve sezonluk kullanım hakkını kontrol edin; sulama planı yapın.",
                "İlk yıl tüm tarlayı riske atmayın; küçük bir pilot alanla başlayın.",
            ]
        else:
            summary = (
                f"For {region}, the strongest option with the available data is {top['crop_name']} "
                f"({top['rule_score']}/100)."
            )
            if second:
                summary += f" Next is {second['crop_name']} ({second['rule_score']}/100)."
            if rainfall is not None and mean_temp is not None:
                summary += (
                    f" The climate is classified as {climate_class}; annual mean temperature is "
                    f"{mean_temp}°C and annual rainfall is {rainfall} mm."
                )
            summary += " This is preliminary decision support; confirm with a local agronomist and a soil test."
            general_risks = [
                "Drought, frost and heat waves can reduce yield.",
                "Input and output price volatility creates financial uncertainty.",
                "NASA POWER data is gridded, not field-scale; soil testing and local observation are required.",
            ]
            general_actions = [
                "Run a soil test for pH, organic matter and nutrients before planting.",
                "Confirm variety and planting calendar with the local extension service or an agronomist.",
                "Check water rights and seasonal water availability; prepare an irrigation plan.",
                "Start with a pilot plot instead of risking the whole farm in year one.",
            ]

        return AIAnalysis(
            summary=summary,
            crops=assessments,
            general_risks=general_risks,
            general_actions=general_actions,
            confidence=confidence,
            notes=(
                "Deterministik kural motoru kullanıldı; LLM çağrısı yapılmadı."
                if tr
                else "Deterministic rule engine was used; no LLM call was made."
            ),
        )

"""Build the configured AI provider with graceful fallback."""

from __future__ import annotations

import logging

from app.ai.anthropic import AnthropicProvider
from app.ai.base import AIProvider, AIProviderError
from app.ai.gemini import GeminiProvider
from app.ai.heuristic import HeuristicProvider
from app.ai.openai_compatible import OpenAICompatibleProvider
from app.config import Settings

logger = logging.getLogger(__name__)

OPENAI_COMPATIBLE_PROVIDERS: dict[str, tuple[str, str]] = {
    "openai": ("https://api.openai.com/v1", "gpt-4.1-mini"),
    "groq": ("https://api.groq.com/openai/v1", "llama-3.3-70b-versatile"),
    "mistral": ("https://api.mistral.ai/v1", "mistral-small-latest"),
    "deepseek": ("https://api.deepseek.com/v1", "deepseek-chat"),
    "xai": ("https://api.x.ai/v1", "grok-3-mini"),
    "together": ("https://api.together.xyz/v1", "meta-llama/Llama-3.3-70B-Instruct-Turbo"),
    "openrouter": ("https://openrouter.ai/api/v1", "google/gemini-2.5-flash"),
    "ollama": ("http://localhost:11434/v1", "llama3.2"),
}

NO_KEY_PROVIDERS = {"ollama"}


def ai_is_configured(settings: Settings) -> bool:
    provider = settings.normalized_ai_provider
    if provider in {"heuristic", "none", "off", ""}:
        return True
    if provider in NO_KEY_PROVIDERS:
        return True
    return bool(settings.ai_api_key)


def build_ai_provider(settings: Settings) -> AIProvider:
    provider = settings.normalized_ai_provider

    if provider in {"heuristic", "none", "off", ""}:
        return HeuristicProvider()

    missing_key = provider not in NO_KEY_PROVIDERS and not settings.ai_api_key
    if missing_key:
        message = f"{provider} için AI_API_KEY tanımlı değil; deterministik motor kullanılacak."
        if not settings.ai_fallback_to_heuristic:
            raise AIProviderError(message)
        logger.warning(message)
        return HeuristicProvider(reason=message)

    if provider in OPENAI_COMPATIBLE_PROVIDERS:
        default_url, default_model = OPENAI_COMPATIBLE_PROVIDERS[provider]
        return OpenAICompatibleProvider(
            name=provider,
            base_url=settings.ai_base_url or default_url,
            api_key=settings.ai_api_key,
            model=settings.ai_model or default_model,
            timeout_seconds=settings.ai_timeout_seconds,
            temperature=settings.ai_temperature,
            max_tokens=settings.ai_max_output_tokens,
            json_mode=settings.ai_json_mode,
        )

    if provider == "custom":
        if not settings.ai_base_url:
            message = "custom sağlayıcı için AI_BASE_URL zorunludur; deterministik motor kullanılacak."
            if not settings.ai_fallback_to_heuristic:
                raise AIProviderError(message)
            logger.warning(message)
            return HeuristicProvider(reason=message)
        return OpenAICompatibleProvider(
            name="custom",
            base_url=settings.ai_base_url,
            api_key=settings.ai_api_key,
            model=settings.ai_model or "default",
            timeout_seconds=settings.ai_timeout_seconds,
            temperature=settings.ai_temperature,
            max_tokens=settings.ai_max_output_tokens,
            json_mode=settings.ai_json_mode,
        )

    if provider == "gemini":
        return GeminiProvider(
            api_key=settings.ai_api_key or "",
            model=settings.ai_model or "gemini-2.5-flash",
            base_url=settings.ai_base_url or "https://generativelanguage.googleapis.com/v1beta",
            timeout_seconds=settings.ai_timeout_seconds,
            temperature=settings.ai_temperature,
            max_tokens=settings.ai_max_output_tokens,
        )

    if provider == "anthropic":
        return AnthropicProvider(
            api_key=settings.ai_api_key or "",
            model=settings.ai_model or "claude-sonnet-4-5",
            base_url=settings.ai_base_url or "https://api.anthropic.com/v1",
            timeout_seconds=settings.ai_timeout_seconds,
            temperature=settings.ai_temperature,
            max_tokens=settings.ai_max_output_tokens,
        )

    message = f"Bilinmeyen AI_PROVIDER '{provider}'; deterministik motor kullanılacak."
    if not settings.ai_fallback_to_heuristic:
        raise AIProviderError(message)
    logger.warning(message)
    return HeuristicProvider(reason=message)

